/**
 * Dashboard sentences: fixed templates over the API counts (UI_DESIGN §4.7). They
 * are never generated by a model. `**…**` marks the computed numbers, which
 * `Sentence` renders in ink.
 */
import type { DashboardBar, DashboardResponse } from '../../../../shared/contracts/dashboard';
import { isUnknownFacetValue } from '../../../../shared/contracts/search';
import { formatCount } from '../../lib/format';

/** `0.045` of 100 → "4.5%"; under 10% one decimal, otherwise whole numbers. */
export function formatPercent(count: number, of: number): string {
  if (of <= 0) return '0%';
  const value = (count / of) * 100;
  return value < 10 ? `${value.toFixed(1)}%` : `${Math.round(value)}%`;
}

const lower = (label: string): string => label.toLowerCase();
const cases = (n: number): string => (n === 1 ? '1 case' : `${formatCount(n)} cases`);

export function topKnown(bars: readonly DashboardBar[]): DashboardBar | undefined {
  return bars.find((bar) => !isUnknownFacetValue(bar.value));
}

function byValue(bars: readonly DashboardBar[], value: string): DashboardBar | undefined {
  return bars.find((bar) => bar.value === value);
}

export function yearsSentence(years: DashboardResponse['years']): string {
  const recent = years.slice(-2);
  const [a, b] = recent;
  if (!a || !b) return 'There are not enough years in this data to compare.';
  const totalA = a.completed + a.other;
  const totalB = b.completed + b.other;
  const ratio = (y: { completed: number }, total: number): number => (total === 0 ? 1 : y.completed / total);
  const first = `**${a.year} has ${formatCount(a.completed)} completed of ${formatCount(totalA)} events**`;
  if (ratio(a, totalA) >= 0.95 && ratio(b, totalB) >= 0.95) {
    return `Investigations take time. ${first}, and ${b.year} ${formatCount(b.completed)} of ${formatCount(totalB)}, so the recent years are close to complete.`;
  }
  const only = ratio(b, totalB) < ratio(a, totalA) ? 'only ' : '';
  return `Investigations take time. ${first}, and ${b.year} ${only}${formatCount(b.completed)} of ${formatCount(totalB)}, so recent years look smaller than they will be.`;
}

export function phaseSentence(phase: readonly DashboardBar[], total: number): string {
  const top = topKnown(phase);
  if (!top) return 'No flight phase is recorded for these cases.';
  return `The defining event was during ${lower(top.label)} in **${cases(top.count)} (${formatPercent(top.count, total)})**, the most of any phase. That counts investigations, not risk per landing.`;
}

export function injurySentence(injury: readonly DashboardBar[], total: number): string {
  const fatal = byValue(injury, 'FATL')?.count ?? 0;
  const none = byValue(injury, 'NONE')?.count ?? 0;
  const noneText =
    none * 2 > total && total > 0
      ? 'more than half had no injuries'
      : `${formatCount(none)} (${formatPercent(none, total)}) had no injuries`;
  return `**${formatCount(fatal)} investigations (${formatPercent(fatal, total)})** involved a fatality; ${noneText}.`;
}

export function weatherSentence(weather: readonly DashboardBar[], total: number): string {
  const imc = byValue(weather, 'IMC')?.count ?? 0;
  const unknown = weather.filter((bar) => isUnknownFacetValue(bar.value)).reduce((sum, bar) => sum + bar.count, 0);
  const base = `**${formatCount(imc)} (${formatPercent(imc, total)})** were in instrument conditions`;
  return unknown > 0 ? `${base}; for ${formatCount(unknown)} the conditions are not recorded.` : `${base}.`;
}

export function categorySentence(category: readonly DashboardBar[], total: number): string {
  const top = topKnown(category);
  if (!top) return 'No aircraft category is recorded for these cases.';
  const heli = byValue(category, 'HELI');
  const head = `The most common category was ${lower(top.label)}, **${cases(top.count)} (${formatPercent(top.count, total)})**.`;
  const tail = heli && heli !== top ? ` Helicopters: **${cases(heli.count)} (${formatPercent(heli.count, total)})**.` : '';
  return `${head}${tail}`;
}

export function mapSentence(map: DashboardResponse['map'], total: number): string {
  const drawn = map.points.length;
  const lacking =
    map.withoutCoordinates === 0
      ? 'Every case has coordinates.'
      : `**${cases(map.withoutCoordinates)}** lack${map.withoutCoordinates === 1 ? 's' : ''} coordinates.`;
  const outside =
    map.outsideFrame > 0
      ? ` ${cases(map.outsideFrame)} ${map.outsideFrame === 1 ? 'falls' : 'fall'} outside the lower 48 (Alaska, Hawaii, territories or waters) and ${map.outsideFrame === 1 ? 'is' : 'are'} not drawn.`
      : '';
  return `Lower 48 shown: ${formatCount(drawn)} of ${formatCount(total)} cases.${outside} ${lacking}`;
}

/**
 * The multi-aircraft overlap statement (A14) under each chart of an aircraft facet: the
 * aircraft category ("aircraft counts") and the phase, which is each aircraft's
 * defining-event phase ("phase counts"). Both count an event once per value any of its
 * aircraft has, so they can add up to more than the total.
 */
export function overlapSentence(multiAircraft: number, total: number, counts: 'aircraft' | 'phase' = 'aircraft'): string | null {
  if (multiAircraft === 0) return null;
  return `${multiAircraft === 1 ? '1 investigation' : `${formatCount(multiAircraft)} investigations`} involved more than one aircraft, so ${counts} counts can add up to more than ${formatCount(total)}.`;
}
